  occurrences: '_calendar_series_occurrences', versions: '_calendar_series_occurrence_versions', resources: '_calendar_series_version_resources',
  claims: '_calendar_series_pending_claims', cellSets: '_calendar_series_cell_sets', cellBuilders: '_calendar_series_cell_builders', cellSeals: '_calendar_series_cell_set_seals', members: '_calendar_series_cell_members',
  selectors: '_calendar_series_working_selectors', workingMembers: '_calendar_series_working_members',
  seals: '_calendar_series_run_seals', publications: '_calendar_series_run_publications', continuationHeads: '_calendar_series_continuation_heads',
