const t = CALENDAR_SERIES_MATERIALIZATION_TABLES;
const key = (field: string) => `TEXT NOT NULL CHECK(length(${field}) BETWEEN 1 AND 128 AND length(trim(${field}))=length(${field}))`;
const hash = (field: string) => `TEXT NOT NULL CHECK(length(${field})=64 AND ${field} NOT GLOB '*[^a-f0-9]*')`;
const integer = (field: string, minimum = 0, maximum = 9007199254740991) => `INTEGER NOT NULL CHECK(typeof(${field})='integer' AND ${field} BETWEEN ${minimum} AND ${maximum})`;
const instant = (field: string) => integer(field, -8640000000000000, 8640000000000000);
const ref = (table: string, nullable = false) => `TEXT${nullable ? '' : ' NOT NULL'} REFERENCES ${table}(id) DEFERRABLE INITIALLY DEFERRED`;
const json = (field: string, kind: 'object' | 'array', bytes: number) => `TEXT NOT NULL CHECK(length(CAST(${field} AS BLOB))<=${bytes} AND CASE WHEN json_valid(${field}) THEN json_type(${field})='${kind}' ELSE 0 END)`;
const identity = { id: 'TEXT PRIMARY KEY NOT NULL', scope_id: "TEXT NOT NULL CHECK(scope_id='application' OR (substr(scope_id,1,7)='tenant:' AND length(scope_id) BETWEEN 8 AND 263))" };
const day = (field: string) => `INTEGER NOT NULL CHECK(typeof(${field})='integer' AND ${field} BETWEEN -8640000000000000 AND 8639999913600000 AND ${field}%86400000=0)`;
const counterColumns = ['candidate_count', 'resource_count', 'claim_count', 'cell_count', 'member_count', 'selector_count', 'working_member_count'] as const;
const emptyCounters = JSON.stringify(Object.fromEntries(counterColumns.map(column => [column, 0])));

